    `;
  }

  if (!html) return;
  detailForm.innerHTML = html;
  detailForm.dataset.draftKey = detailDraftKey(detail);
  restoreDetailDraft(detailForm.dataset.draftKey);
  detailForm.classList.remove("is-hidden");
}

